 '>' + '← Volver' + '</button>' + '<div class="query-actions-right">' + '<button' + ' type="button"' + ' class="btn-primary"' + ' data-action="save-query"' + '>' + 'Guardar consulta' + '</button>' + '</div>' + '</div>' + '</section>';
