appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  var role = 'viewer';

  var model = appsmith.model || {};

  var maxGroups = parseInt(
    model.query_max_groups || 3,
    10
  );

  if (isNaN(maxGroups) || maxGroups < 1) {
    maxGroups = 3;
  }

  var savedQueriesPageSize = parseInt(
    model.queries_page_size || 3,
    10
  );

  if (
    isNaN(savedQueriesPageSize) ||
    savedQueriesPageSize < 1
  ) {
    savedQueriesPageSize = 3;
  }

  var savedQueriesPage = 1;

  var queryState = {
    step: 1,
    groups: [
      {
        groupNo: 1,
        include: [],
        and: [],
        andNot: []
      }
    ],
    selectedTargets: {},
    useWeb: false,
    name: '',
    status: 'active'
  };

  function decodeB64(value) {
    if (!value) {
      return [];
    }

    try {
      return JSON.parse(
        decodeURIComponent(
          escape(
            atob(value)
          )
        )
      );
    } catch (error) {
      return [];
    }
  }

  function esc(value) {
    var element =
      document.createElement('div');

    element.textContent =
      value == null
        ? ''
        : String(value);

    return element.innerHTML;
  }

  function normalizeText(value) {
    return String(value || '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function quoteTerm(value) {
    return '"' +
      String(value || '')
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"') +
      '"';
  }

  function getTargets() {
    return decodeB64(
      (appsmith.model || {}).targetsJson || ''
    );
  }

  function getQueries() {
    return decodeB64(
      (appsmith.model || {}).queriesJson || ''
    );
  }

  function getSelectedTargets() {
    return getTargets().filter(function (target) {
      return !!queryState.selectedTargets[target.id];
    });
  }

  function renumberGroups() {
    queryState.groups.forEach(function (group, index) {
      group.groupNo = index + 1;
    });
  }

  function totalTerms() {
    var total = 0;

    queryState.groups.forEach(function (group) {
      total += group.include.length;
      total += group.and.length;
      total += group.andNot.length;
    });

    return total;
  }

  function buildGroupFormula(group) {
    var parts = [];

    if (group.include.length > 0) {
      var includeExpression =
        group.include
          .map(quoteTerm)
          .join(' OR ');

      if (group.include.length > 1) {
        includeExpression =
          '(' +
          includeExpression +
          ')';
      }

      parts.push(
        includeExpression
      );
    }

    group.and.forEach(function (term) {
      parts.push(
        'AND ' +
        quoteTerm(term)
      );
    });

    group.andNot.forEach(function (term) {
      parts.push(
        'AND NOT ' +
        quoteTerm(term)
      );
    });

    return parts.join(' ');
  }

  function buildFormula() {
    var formulas = [];

    queryState.groups.forEach(function (group) {
      var formula =
        buildGroupFormula(group);

      if (formula) {
        formulas.push(formula);
      }
    });

    if (formulas.length === 0) {
      return '';
    }

    if (formulas.length === 1) {
      return formulas[0];
    }

    return formulas
      .map(function (formula) {
        return (
          '(' +
          formula +
          ')'
        );
      })
      .join(' OR ');
  }

  function showMessage(
    message,
    type
  ) {
    var box =
      document.getElementById(
        'queryMessage'
      );

    if (!box) {
      return;
    }

    box.className =
      'query-message show ' +
      (type || 'info');

    box.textContent =
      message;
  }

  function clearMessage() {
    var box =
      document.getElementById(
        'queryMessage'
      );

    if (!box) {
      return;
    }

    box.className =
      'query-message';

    box.textContent =
      '';
  }

  function setSaveButtonState(
    disabled,
    label
  ) {
    var button =
      document.querySelector(
        '[data-action="save-query"]'
      );

    if (!button) {
      return;
    }

    button.disabled =
      !!disabled;

    if (label) {
      button.textContent =
        label;
    }
  }

  function formatDate(value) {
    if (!value) {
      return '';
    }

    try {
      return new Intl.DateTimeFormat(
        'es',
        {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric'
        }
      ).format(
        new Date(value)
      );
    } catch (error) {
      return '';
    }
  }

  function validateBuild() {
    if (
      queryState.groups.length === 0
    ) {
      return (
        'Debes crear al menos un grupo.'
      );
    }

    for (
      var i = 0;
      i < queryState.groups.length;
      i++
    ) {
      if (
        queryState.groups[i]
          .include.length === 0
      ) {
        return (
          'El Grupo ' +
          (i + 1) +
          ' necesita al menos un término en INCLUIR.'
        );
      }
    }

    return '';
  }

  function addTerm(
    groupIndex,
    bucket,
    rawValue
  ) {
    var value =
      normalizeText(
        rawValue
      );

    if (!value) {
      return;
    }

    var group =
      queryState.groups[
        groupIndex
      ];

    if (
      !group ||
      !group[bucket]
    ) {
      return;
    }

    var exists =
      group[bucket].some(
        function (item) {
          return (
            item.toLowerCase() ===
            value.toLowerCase()
          );
        }
      );

    if (!exists) {
      group[bucket].push(
        value
      );
    }

    renderCurrentStep();
  }

  function removeTerm(
    groupIndex,
    bucket,
    termIndex
  ) {
    var group =
      queryState.groups[
        groupIndex
      ];

    if (
      !group ||
      !group[bucket]
    ) {
      return;
    }

    group[bucket].splice(
      termIndex,
      1
    );

    renderCurrentStep();
  }

  function renderSavedQueries() {
    var container =
      document.getElementById(
        'savedQueriesArea'
      );

    if (!container) {
      return;
    }

    var queries =
      getQueries();

    var totalPages =
      Math.max(
        1,
        Math.ceil(
          queries.length /
          savedQueriesPageSize
        )
      );

    if (
      savedQueriesPage >
      totalPages
    ) {
      savedQueriesPage =
        totalPages;
    }

    if (
      savedQueriesPage <
      1
    ) {
      savedQueriesPage = 1;
    }

    var startIndex =
      (
        savedQueriesPage -
        1
      ) *
      savedQueriesPageSize;

    var visibleQueries =
      queries.slice(
        startIndex,
        startIndex +
          savedQueriesPageSize
      );

    var html =
      '<section class="saved-queries-panel">' +

        '<div class="saved-queries-head">' +

          '<div>' +

            '<span class="query-eyebrow">' +
              'Biblioteca' +
            '</span>' +

            '<h3>' +
              'Consultas guardadas' +
            '</h3>' +

            '<p>' +
              'Contextos disponibles para esta cuenta.' +
            '</p>' +

          '</div>' +

          '<span class="saved-queries-count">' +
            esc(
              queries.length
            ) +
          '</span>' +

        '</div>';

    if (
      queries.length === 0
    ) {
      html +=
        '<div class="targets-empty">' +
          'Todavía no hay consultas guardadas.' +
        '</div>';
    } else {
      html +=
        '<div class="saved-query-list">';

      visibleQueries.forEach(
        function (query) {
          var statusLabel =
            query.status ===
            'active'
              ? 'Activa'
              : 'Inactiva';

          html +=
            '<article class="saved-query-card">' +

              '<div class="saved-query-card-head">' +

                '<div class="saved-query-title">' +

                  '<strong>' +
                    esc(
                      query.name ||
                      ''
                    ) +
                  '</strong>' +

                  '<span>' +
                    esc(
                      formatDate(
                        query.updated_at ||
                        query.created_at
                      )
                    ) +
                  '</span>' +

                '</div>' +

                '<span class="saved-query-status ' +
                  (
                    query.status ===
                    'active'
                      ? 'active'
                      : 'inactive'
                  ) +
                '">' +
                  esc(
                    statusLabel
                  ) +
                '</span>' +

              '</div>' +

              '<div class="saved-query-formula">' +
                esc(
                  query.formula_text ||
                  ''
                ) +
              '</div>' +

              '<div class="saved-query-metrics">' +

                '<span>' +
                  '<strong>' +
                    esc(
                      query.groups_count ||
                      0
                    ) +
                  '</strong>' +
                  ' grupo(s)' +
                '</span>' +

                '<span>' +
                  '<strong>' +
                    esc(
                      query.terms_count ||
                      0
                    ) +
                  '</strong>' +
                  ' término(s)' +
                '</span>' +

                '<span>' +
                  '<strong>' +
                    esc(
                      query.targets_count ||
                      0
                    ) +
                  '</strong>' +
                  ' objetivo(s)' +
                '</span>' +

              '</div>' +

              '<div class="saved-query-sources">' +

                '<span>' +
                  'Web: ' +
                  (
                    query.use_web
                      ? 'Sí'
                      : 'No'
                  ) +
                '</span>' +

              '</div>' +

            '</article>';
        }
      );

      html +=
        '</div>' +

        '<div class="query-actions">' +

          '<button' +
            ' type="button"' +
            ' class="btn-secondary"' +
            ' data-action="saved-prev"' +
            (
              savedQueriesPage <= 1
                ? ' disabled'
                : ''
            ) +
          '>' +
            '← Anterior' +
          '</button>' +

          '<span class="query-status-pill">' +
            'Página ' +
            esc(
              savedQueriesPage
            ) +
            ' de ' +
            esc(
              totalPages
            ) +
          '</span>' +

          '<button' +
            ' type="button"' +
            ' class="btn-secondary"' +
            ' data-action="saved-next"' +
            (
              savedQueriesPage >=
              totalPages
                ? ' disabled'
                : ''
            ) +
          '>' +
            'Siguiente →' +
          '</button>' +

        '</div>';
    }

    html +=
      '</section>';

    container.innerHTML =
      html;

    var list =
      container.querySelector(
        '.saved-query-list'
      );

    if (list) {
      list.style.maxHeight =
        'none';

      list.style.overflowY =
        'visible';

      list.style.paddingRight =
        '0';
    }
  }

  function buildStepper() {
    var steps = [
      {
        number: 1,
        label: 'Construir',
        caption:
          'Reglas y fuentes'
      },
      {
        number: 2,
        label: 'Previsualizar',
        caption:
          'Validar consulta'
      },
      {
        number: 3,
        label: 'Guardar',
        caption:
          'Nombre y estado'
      }
    ];

    var html = '';

    steps.forEach(
      function (step, index) {
        var stateClass = '';

        if (
          queryState.step ===
          step.number
        ) {
          stateClass =
            ' active';
        } else if (
          queryState.step >
          step.number
        ) {
          stateClass =
            ' done';
        }

        html +=
          '<div class="step-item' +
          stateClass +
          '">' +

            '<div class="step-number">' +
              esc(
                step.number
              ) +
            '</div>' +

            '<div class="step-copy">' +

              '<span class="step-label">' +
                esc(
                  step.label
                ) +
              '</span>' +

              '<span class="step-caption">' +
                esc(
                  step.caption
                ) +
              '</span>' +

            '</div>' +

          '</div>';

        if (
          index <
          steps.length - 1
        ) {
          html +=
            '<div class="step-line' +
            (
              queryState.step >
              step.number
                ? ' done'
                : ''
            ) +
            '"></div>';
        }
      }
    );

    return html;
  }

  function renderChips(
    groupIndex,
    bucket,
    values,
    isExclude
  ) {
    if (
      !values ||
      values.length === 0
    ) {
      return '';
    }

    var html =
      '<div class="term-chips">';

    values.forEach(
      function (
        term,
        index
      ) {
        html +=
          '<span class="term-chip' +
          (
            isExclude
              ? ' exclude'
              : ''
          ) +
          '">' +

            '<span class="term-chip-text">' +
              esc(term) +
            '</span>' +

            '<button' +
              ' type="button"' +
              ' class="term-chip-remove"' +
              ' data-action="remove-term"' +
              ' data-group="' +
                esc(
                  groupIndex
                ) +
              '"' +
              ' data-bucket="' +
                esc(
                  bucket
                ) +
              '"' +
              ' data-index="' +
                esc(
                  index
                ) +
              '"' +
              ' aria-label="Eliminar término"' +
            '>×</button>' +

          '</span>';
      }
    );

    html +=
      '</div>';

    return html;
  }

  function renderRuleRow(
    groupIndex,
    bucket,
    label,
    help,
    placeholder,
    isExclude
  ) {
    var group =
      queryState.groups[
        groupIndex
      ];

    return (
      '<div class="rule-row">' +

        '<div class="rule-meta">' +

          '<span class="rule-label' +
          (
            isExclude
              ? ' exclude'
              : ''
          ) +
          '">' +
            esc(
              label
            ) +
          '</span>' +

          '<span class="rule-help">' +
            esc(
              help
            ) +
          '</span>' +

        '</div>' +

        '<div class="term-area">' +

          '<div class="term-entry">' +

            '<input' +
              ' class="term-input"' +
              ' type="text"' +
              ' autocomplete="off"' +
              ' data-term-input="1"' +
              ' data-group="' +
                esc(
                  groupIndex
                ) +
              '"' +
              ' data-bucket="' +
                esc(
                  bucket
                ) +
              '"' +
              ' placeholder="' +
                esc(
                  placeholder
                ) +
              '"' +
            '>' +

            '<button' +
              ' type="button"' +
              ' class="btn-add-term"' +
              ' data-action="add-term"' +
              ' data-group="' +
                esc(
                  groupIndex
                ) +
              '"' +
              ' data-bucket="' +
                esc(
                  bucket
                ) +
              '"' +
            '>' +
              'Agregar' +
            '</button>' +

          '</div>' +

          renderChips(
            groupIndex,
            bucket,
            group[bucket],
            isExclude
          ) +

        '</div>' +

      '</div>'
    );
  }

  function renderGroup(
    group,
    index
  ) {
    var removeButton =
      '';

    if (
      queryState.groups.length >
      1
    ) {
      removeButton =
        '<button' +
          ' type="button"' +
          ' class="btn-link-danger"' +
          ' data-action="remove-group"' +
          ' data-group="' +
            esc(
              index
            ) +
          '"' +
        '>' +
          'Eliminar grupo' +
        '</button>';
    }

    var html =
      '<div class="rule-group">' +

        '<div class="rule-group-head">' +

          '<div class="rule-group-title">' +

            '<span class="group-badge">' +
              esc(
                group.groupNo
              ) +
            '</span>' +

            '<div>' +

              '<strong>' +
                'Grupo ' +
                esc(
                  group.groupNo
                ) +
              '</strong>' +

              '<span>' +
                'Reglas de coincidencia' +
              '</span>' +

            '</div>' +

          '</div>' +

          removeButton +

        '</div>' +

        '<div class="rule-group-body">' +

          renderRuleRow(
            index,
            'include',
            'Incluir',
            'Uno o varios términos. Entre ellos se aplica OR.',
            'Añade una palabra o frase',
            false
          ) +

          renderRuleRow(
            index,
            'and',
            'AND',
            'El resultado también debe contener estos términos.',
            'Añade una condición obligatoria',
            false
          ) +

          renderRuleRow(
            index,
            'andNot',
            'AND NOT',
            'Excluir resultados que contengan estos términos.',
            'Añade un término a excluir',
            true
          ) +

        '</div>' +

      '</div>';

    if (
      index <
      queryState.groups.length - 1
    ) {
      html +=
        '<div class="group-connector">' +
          '<span>OR</span>' +
        '</div>';
    }

    return html;
  }

  function renderTargetChoices() {
    var rows =
      getTargets();

    if (
      rows.length === 0
    ) {
      return (
        '<div class="targets-empty">' +
          'No hay objetivos sociales disponibles para esta cuenta.' +
        '</div>'
      );
    }

    var html =
      '<div class="targets-grid">';

    rows.forEach(
      function (target) {
        var active =
          target.status ===
          'active';

        var selected =
          !!queryState
            .selectedTargets[
              target.id
            ];

        var displayName =
          target.handle ||
          target.external_profile_id ||
          'Objetivo';

        html +=
          '<label class="target-choice' +
          (
            selected
              ? ' selected'
              : ''
          ) +
          (
            !active
